import{c as t,Q as e,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"SetFmatrixBitMode","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetFmatrixBitMode","slug":"setfmatrixbitmode"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetFmatrixBitMode.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetFmatrixBitMode.md"}'),i={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/SetFmatrixBitMode.md"};function p(d,a,l,o,r,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="setfmatrixbitmode" tabindex="-1">SetFmatrixBitMode <a class="header-anchor" href="#setfmatrixbitmode" aria-label="Permalink to &quot;SetFmatrixBitMode&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>x</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于调用<a href="./LoadData/LoadData.html">Load3Dv1/Load3Dv2</a>时设置FeatureMap的属性描述。Load3Dv1/Load3Dv2的模板参数isSetFMatrix设置为false时，表示Load3Dv1/Load3Dv2传入的FeatureMap的属性（包括l1H、l1W、padList，参数介绍参考<a href="./LoadData/Load3D.html#table679014222918">表4 LoadData3DParamsV1结构体内参数说明</a>、<a href="./LoadData/Load3D.html#table193501032193419">表5 LoadData3DParamsV2结构体内参数说明</a>）描述不生效，开发者需要通过该接口进行设置。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void SetFmatrix(const SetFMatrixBitModeParams&amp; param, const FmatrixMode&amp; fmatrixMode)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>fmatrixMode</td><td>输入</td><td>用于控制LoadData指令从left还是right寄存器获取信息。FmatrixMode类型，定义如下。当前只支持FMATRIX_LEFT，左右矩阵均使用该配置。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1488815152539&quot;&gt;enum class FmatrixMode : uint8_t { FMATRIX_LEFT = 0, FMATRIX_RIGHT = 1, }; &lt;/pre&gt;</td></tr><tr><td>param</td><td>输入</td><td>类型为SetFMatrixBitMode，具体参考表2。</td></tr></tbody></table><p><strong>表 2</strong> SetFMatrixBitMode类参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>config0</td><td>uint64_t类型，与SetFMatrixBitModeConfig0位域（bit-field）结构体类型参数config0BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig0()函数获取其值。</td></tr><tr><td>config0BitMode</td><td>SetFMatrixBitModeConfig0位域（bit-field）结构体类型，参数参考表3，与config0组成联合体（union）。</td></tr></tbody></table><p>SetFMatrixBitMode类参数设计思想说明：</p><p>联合体（union）是一种特殊的数据结构，允许在相同的内存位置存储不同的数据类型。union的所有成员共享同一块内存空间，大小由最大成员决定，同一时间只能使用一个成员。</p><p>位域（bit-field）是一种特殊的类成员，允许精确控制结构体中成员变量所占用的内存位数。结构体中成员变量从上到下对应内存中从低位到高位。</p><p>SetFMatrixBitMode类使用union与bit-field方法，采用bit位表达参数类型，使用bit-field结构体自动处理入参的bit位数，并利用union的特性实现多参数融合传递，仅需传递一个入参即可包含全部所需信息，对应底层接口仅需要接收一个参数。同时，当需要修改参数中某一bit位的值时，仅需要通过循环和位运算即可实现，不需要重新传入参数，减少了scalar计算，实现性能提升。</p><p>SetFMatrixBitMode类可以直接使用LoadData3DParamsV2结构体类型对象初始化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline SetFMatrixBitModeParams(const LoadData3DParamsV2&lt;T&gt; &amp;loadData3DParams_);</span></span></code></pre></div><p>也可以使用各参数的Set函数修改参数值，并且由于使用了联合体，还可以对congfig0直接进行逐bit位修改来修改参数。</p><p><strong>表 3</strong> SetFMatrixBitModeConfig0结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>l1H</td><td>源操作数height，取值范围：l1H∈[1, 32767]。 该参数是位域结构体的最低位参数，占用16bit，可以使用SetFMatrixBitMode类对象的SetL1H()函数设置其值。</td></tr><tr><td>l1W</td><td>源操作数width，取值范围：l1W∈[1, 32767] 。 该参数是位域结构体的第二低位参数，占用16bit，可以使用SetFMatrixBitMode类对象的SetL1W()函数设置其值。</td></tr><tr><td>padList0</td><td>对应表1中padding列表中的 padding_left值，取值范围：[0,255]。默认为0。 该参数是位域结构体的第三低位参数，占用8bit，可以使用SetFMatrixBitMode类对象的SetPadList()函数设置其值。</td></tr><tr><td>padList1</td><td>对应表1中padding列表中的 padding_right值，取值范围：[0,255]。默认为0。 该参数是位域结构体的第四低位参数，占用8bit，可以使用SetFMatrixBitMode类对象的SetPadList()函数设置其值。</td></tr><tr><td>padList2</td><td>对应表1中padding列表中的 padding_top值，取值范围：[0,255]。默认为0。 该参数是位域结构体的第五低位参数，占用8bit，可以使用SetFMatrixBitMode类对象的SetPadList()函数设置其值。</td></tr><tr><td>padList3</td><td>对应表1中padding列表中的 padding_bottom值，取值范围：[0,255]。默认为0。 该参数是位域结构体的最高位参数，占用8bit，可以使用SetFMatrixBitMode类对象的SetPadList()函数设置其值。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>该接口需要配合load3Dv1/load3Dv2接口一起使用，需要在load3Dv1/load3Dv2接口之前调用。</li><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::A1, 1&gt; inQueueFmA1;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::A2, 1&gt; inQueueFmA2;</span></span>
<span class="line"><span>// weight queue</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::B1, 1&gt; inQueueWeB1;</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::B2, 1&gt; inQueueWeB2;</span></span>
<span class="line"><span>pipe.InitBuffer(inQueueFmA1, 1, featureMapA1Size * sizeof(fmap_T));</span></span>
<span class="line"><span>pipe.InitBuffer(inQueueFmA2, 1, featureMapA2Size * sizeof(fmap_T));</span></span>
<span class="line"><span>pipe.InitBuffer(inQueueWeB1, 1, weightA1Size * sizeof(weight_T));</span></span>
<span class="line"><span>pipe.InitBuffer(inQueueWeB2, 1, weightB2Size * sizeof(weight_T));</span></span>
<span class="line"><span>pipe.InitBuffer(outQueueCO1, 1, dstCO1Size * sizeof(dstCO1_T));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::LocalTensor&lt;fmap_T&gt; featureMapA1 = inQueueFmA1.DeQue&lt;fmap_T&gt;();</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;weight_T&gt; weightB1 = inQueueWeB1.DeQue&lt;weight_T&gt;();</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;fmap_T&gt; featureMapA2 = inQueueFmA2.AllocTensor&lt;fmap_T&gt;();</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;weight_T&gt; weightB2 = inQueueWeB2.AllocTensor&lt;weight_T&gt;();</span></span>
<span class="line"><span>uint16_t channelSize = 32;</span></span>
<span class="line"><span>uint16_t H = 4, W = 4;</span></span>
<span class="line"><span>uint8_t Kh = 2, Kw = 2;</span></span>
<span class="line"><span>uint16_t Cout = 16;</span></span>
<span class="line"><span>uint16_t C0, C1;</span></span>
<span class="line"><span>uint8_t dilationH = 2, dilationW = 2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uint8_t padList[PAD_SIZE] = {0, 0, 0, 0};</span></span>
<span class="line"><span>AscendC::SetFmatrix(H, W, padList, FmatrixMode::FMATRIX_LEFT);</span></span>
<span class="line"><span>/*  </span></span>
<span class="line"><span>SetFMatrixBitModeParams param;</span></span>
<span class="line"><span>param.SetL1H(H);</span></span>
<span class="line"><span>param.SetL1W(W);</span></span>
<span class="line"><span>param.SetPadList(padList);</span></span>
<span class="line"><span>AscendC::SetFmatrix(param, FmatrixMode::FMATRIX_LEFT);</span></span>
<span class="line"><span>*/ </span></span>
<span class="line"><span>AscendC::SetLoadDataPaddingValue(0);</span></span>
<span class="line"><span>AscendC::SetLoadDataRepeat({0, 1, 0});</span></span>
<span class="line"><span>AscendC::SetLoadDataBoundary((uint32_t)0);</span></span>
<span class="line"><span>static constexpr AscendC::IsResetLoad3dConfig LOAD3D_CONFIG = {false,false};</span></span>
<span class="line"><span>AscendC::LoadData&lt;fmap_T, LOAD3D_CONFIG&gt;(featureMapA2, featureMapA1,</span></span>
<span class="line"><span>    { padList, H, W, channelSize, k, howoRound, 0, 0, 1, 1, Kw, Kh, dilationW, dilationH, false, false, 0 });</span></span>
<span class="line"><span>AscendC::LoadData(weightB2, weightB1, { 0, weRepeat, 1, 0, 0, false, 0 });</span></span>
<span class="line"><span></span></span>
<span class="line"><span>inQueueFmA2.EnQue&lt;fmap_T&gt;(featureMapA2);</span></span>
<span class="line"><span>inQueueWeB2.EnQue&lt;weight_T&gt;(weightB2);</span></span>
<span class="line"><span>inQueueFmA1.FreeTensor(featureMapA1);</span></span>
<span class="line"><span>inQueueWeB1.FreeTensor(weightB1);</span></span></code></pre></div>`,25)])])}const g=t(i,[["render",p]]);export{h as __pageData,g as default};
